// Sales tax for a cart subtotal, in cents.
export const TAX_RATE = 0.07;

export function taxCents(subtotalCents) {
  return Math.floor(subtotalCents * TAX_RATE);
}

overlay.src/cart.mjs:
import { taxCents } from './tax.mjs';

// Order total in cents: item subtotal plus sales tax.
export function orderTotalCents(items) {
  const subtotal = items.reduce((sum, it) => sum + it.priceCents * it.qty, 0);
  return subtotal + taxCents(subtotal);
}
